// 1. 读取已完成的生成任务，拿到权威 resultRef
const task = await app.action('get_generation_task', { taskId: 'task-1786965571549-hdjwo7i' });
app.assert.equal(task.task.status, 'completed');

const resultRef = task.task.result_ref;
app.assert.exists(resultRef);

// 2. 创建画布工程
const project = await app.action('create_canvas_project', { name: '自动验收-{{nonce}}-生成画布' });
const projectId = project.projectId;
app.assert.exists(projectId);

// 3. 将生成结果放入画布
const placed = await app.action('add_generation_result_to_canvas', {
  projectId,
  resultRef: { kind: 'generation.result', id: resultRef.id },
  placement: { mode: 'auto' }
});
app.assert.exists(placed.nodeId);

// 4. 读取正式画布工程，确认媒体节点存在
const canvas = await app.action('get_canvas_project', { projectId });
const foundNode = canvas.nodes.find((n: any) => n.nodeId === placed.nodeId);
app.assert.exists(foundNode);
app.assert.equal(canvas.project.name, '自动验收-{{nonce}}-生成画布');
